// eslint-disable-next-line @typescript-eslint/no-namespace
namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokHromadnePrideleniTab extends GContentBase {
    
        pokDoklady: Gordic.Hpl.Interface.GPokDokladDto[];
        private subrada: string;
        private ixpDen: string;

        onContentReady() {

            var that = this;


            var gf = new Gordic.Data.GridFormat();
            gf.addTextColumn({
                name: "ixp",
                caption: "jres:31302005", //RC 31302005 : PID
                sortable: false
            });         

            const gridActionDetail = new GAction($.extend(true, Gordic.Eko.Action.actionDetail({
                run: function (ev, ctx) {
                    that.navigate("Gordic.Pok.WebClient.GPokDetailDokladuTab", {
                        ixp: ctx.cellInfo.data.ixp,
                        newPodani: false,
                        Id: "GPokDetailDokladu#"
                    });
                },
                enabled: true
            }), { name: "actDetail" }))


            this.navigate<Gordic.Eko.Components.TwoStepsOptions<Gordic.Hpl.Interface.GPokDokladDto>>(Gordic.Eko.Components.TwoStepsContent, {
                title: "Hromadné přidělení dokumentu",
                gridFormat: gf,
                keys: "ixp",
                data: this.pokDoklady,
                indicatorType: "KPI",
                firstStep: {
                    title: "Hromadné přidělení dokumentu",
                    description: "Kontrola a doplnění údajů pro přidělení dokumentu",
                    gridTabTitle: "Vybrané pokladní doklady",
                    defaultAction: gridActionDetail,
                    form:  Gordic.Eko.Prefabs.PrideleniDokladuForm({
                        SouvisejiciViditelnost: false,
                        SouvisejiciZmena: false,
                        StartFiltrZpracovatel: {
                            DlePovolenychFazi: ["GWAPOK05", "GSAPOK01"], //that.gpc.faze
                            VrfuTypAg: "pok",
                            VrfuAktivita: 100,
                            VrfuIxpDen: that.ixpDen,
                            VrfuSubrada: that.subrada,
                            aktivita: 100,
                            ReferentAktivita: 100
                        },
                        KompetentViditelnost: false

                    }),
                    checkAction: (model, data) => {


                        var view = new Gordic.Data.View(data, { key: "ixp" });
                        var ixpArray = data.map(function (d) { return d.ixp; });
                        let i = 0;

                        let def = $.Deferred();

                        ixpArray.forEach(function (x) {

                            that.isl.PokDoklad.seznamPermissions(rq => { return { ixp: x } }).get()
                                .done(function (data) {

                                    view.getDataRows(true).forEach(function (meta) {

                                    

                                        if (meta.data.ixp === x) {


                                            i = i + 1;

                                            meta.data.wiz_kind = data.LzePridelitFunkci.value ? Gordic.Isl.GOperationResultKind.Success : Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = data.LzePridelitFunkci.message;
                                            meta.data.wiz_check = data.LzePridelitFunkci.value;
                                        }

                                        if (i == ixpArray.length) {
                                            def.resolve(view)
                                        }
                                    });

                                })
                                .fail(function (xhr, type, vobj) {

                                    view.getDataRows(true).forEach(function (meta) {
                                        vobj.handled = true;
                                        if (meta.data.ixp === x) {
                                            i = i + 1;
                                            meta.data.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            meta.data.wiz_txt_err = vobj.baseMessage;
                                            meta.data.wiz_check = false;
                                        }

                                        if (i == ixpArray.length) {
                                            def.resolve(view)
                                        }
                                    });


                                });
                        })
                        return def.promise();
                    },
                    nextActionName: "Přidělit",
                    nextAction: (model, data) => {

                        let def = $.Deferred();
                        let y = 0;

                        if (data.length == 0)
                            def.resolve(data);


                        data.forEach(function (row) {
                            that.isl.PokDoklad.pridelitDoklad(
                                rq => {
                                    return {
                                        ixp: row.ixp,
                                        duvod: model.duvod,
                                        ixsFunPrijemce: model.ixs_fun_akt,
                                        ixsSuPrijemce: model.ixs_su

                                    }
                                })
                                .get()
                                .done(function () {
                                    row.wiz_kind = Gordic.Isl.GOperationResultKind.Success;
                                    row.wiz_txt_err = "Doklad byl úspěšně přidělen!";
                                })
                                .fail(function (xhr, type, vobj) {
                                    if (type === "exception") {
                                        if (vobj.baseType === "Gordic.General.GHplValidationException") {
                                            vobj.handled = true;
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            row.wiz_txt_err = vobj.baseMessage;

                                        }                                      
                                        else {
                                            vobj.handled = true;
                                            row.wiz_kind = Gordic.Isl.GOperationResultKind.Error;
                                            row.wiz_txt_err = vobj.baseMessage;

                                        }
                                    }
                                })
                                .always(function () {
                                    y = y + 1;

                                    if (y == data.length) {
                                        def.resolve(data)
                                    }
                                });

                        });

                        return def.promise();

                    },
                },
                lastStep:
                {
                    title: "Výsledek",
                    gridTabTitle: "Seznam přidělených dokumentů",
                    description: "Výsledek hromadného storna"
                },
                completeDelegate: (view) => {

                    that.close(true);
                },
                cancelDelegate: () => {
                    that.close(false);
                },
            }, { title: "Hromadné přidělení dokumentů" });

        }








    }


}


